export function useDebouncedRef(value, delay = 200) {
  let timeout;
  return customRef((track, trigger) => ({
    get() {
      track();
      return value;
    },
    set(newValue) {
      value = newValue;
      clearTimeout(timeout);
      timeout = setTimeout(() => {
        trigger();
      }, delay);
    }
  }));
}

